fn atomic_reorg_with_readback<'db>(
    &'db self,
    progress: &mut dyn FnMut() -> Result<()>,
    run: impl FnOnce(
        &mut dyn FnMut() -> Result<()>,
        Option<&trnm_sqlite_io_boundary::TransactionScope<'db>>,
    ) -> Result<Option<native_authenticated::PostWriteReadback<'db>>>,
) -> Result<()> {
    progress()?;
    let tx = rusqlite::Transaction::new_unchecked(
        &self.db,
        rusqlite::TransactionBehavior::Immediate,
    )?;
    let original_owner = (self.state_backend == StateBackend::AuthenticatedV1)
        .then(|| {
            trnm_sqlite_io_boundary::TransactionScope::capture(&self.db)
                .map_err(native_authenticated::readback_scope_error)
        })
        .transpose()?;
    let transaction_result: Result<()> = (|| {
        let mut readback = run(progress, original_owner.as_ref())?;
        self.check_active_before_commit_with_readback(progress, readback.as_mut())?;
        self.continuous_scope_checkpoint()?;
        self.mining_scope_checkpoint()?;
        progress()?;
        if let Some(scope) = readback.as_mut() {
            // No legitimate write remains after the closure's explicit
            // boundary. This must follow the LAST caller callback, even
            // when no duplicate graph was consumed by the atomic tail.
            scope.require_unchanged_after_last_write(&self.db)?;
        }
        Ok(())
    })();
    // As in admission, a callback's transaction replacement cannot hide
    // behind an ordinary error/cancellation. Preserve that first error as
    // the source; a write alone does not override a failing callback.
    let transaction_result = match original_owner
        .as_ref()
        .map(|owner| owner.same_write_snapshot(&self.db))
        .transpose()
    {
        Ok(_) => transaction_result,
        Err(error) => Err(match transaction_result {
            Ok(()) => native_authenticated::readback_scope_error(error),
            Err(first) => Error::local_replay_source("NATIVE_POST_WRITE_SCOPE", first),
        }),
    };
    transaction_result?;
    let commit_observation = (self.state_backend == StateBackend::AuthenticatedV1).then(|| {
        self.authenticated_arithmetic
            .history
            .observe_sql_commit(native_authenticated::SqlCommitSite::ReorgStep)
    });
    let commit_result = tx.commit();
    if let Some(observation) = commit_observation {
        observation.finish_sql_result(&commit_result);
    }
    commit_result?;
    Ok(())

    let mut detached = 0i64;
    let mut attached = 0i64;
    while left != right {
        progress()?;
        if self.record(left)?.height >= self.record(right)?.height {
            self.db.execute(
                "INSERT INTO steps VALUES(?,0,?)",
                params![detached, left.as_slice()],
            )?;
            detached = detached.checked_add(1).ok_or("ANCESTRY_LIMIT")?;
            left = self.parent(left)?;
        } else {
            attached = attached.checked_add(1).ok_or("ANCESTRY_LIMIT")?;
            self.db.execute(
                "INSERT INTO steps VALUES(?,1,?)",
                params![-attached, right.as_slice()],
            )?;
            right = self.parent(right)?;
        }
    }
    let count = detached.checked_add(attached).ok_or("ANCESTRY_LIMIT")?;
    self.db.execute(
        "UPDATE steps SET ordinal=?+ordinal WHERE ordinal<0",
        [count],
    )?;
    self.db.execute(
        "INSERT OR REPLACE INTO reorg VALUES(1,?,?,?,0,0)",
        params![old.as_slice(), target.as_slice(), next],
    )?;
    self.insert_reorg_lifecycle(&mut cancellation)?;
    ensure(
        self.active()? == (old, g)
            && self.check_steps_with_progress(old, target, 0, progress)? == count as u64,
        "REORG_STEPS",
    )
    .map_err(Error::local_integrity)?;
    self.check_reorg_row(old, target, next, 0, 0)?;
    let mut readback = self.reorg_post_write_readback(old, original_owner)?;
    self.check_persisted_state_with_readback(
        old,
        &self.slot_state_with_progress(next, progress)?,
        progress,
        readback.as_mut(),
    )?;
    Ok(readback)
})?;

let count = self.check_steps_with_progress(old, target, position, progress)?;
for index in position..count {
    progress()?;
    let (kind, bytes) = self.db.query_row(
        "SELECT kind,block FROM steps WHERE ordinal=?",
        [index],
        |r| Ok((r.get::<_, u64>(0)?, r.get::<_, Vec<u8>>(1)?)),
    )?;
    let id = bytes32(bytes)?;
    self.atomic_reorg_with_readback(progress, |progress, original_owner| {
        self.apply_delta_with_progress(id, g, kind == 0, progress)?;
        ensure(
            self.db
                .execute("UPDATE reorg SET cursor=? WHERE singleton=1", [index + 1])?
                == 1,
            "STORAGE_WRITE",
        )
        .map_err(Error::local_integrity)?;
        self.check_reorg_row(old, target, g, index + 1, 0)?;
        let resulting = if kind == 0 { self.parent(id)? } else { id };
        let mut readback = self.reorg_post_write_readback(resulting, original_owner)?;
        self.check_persisted_state_with_readback(
            resulting,
            &self.slot_state_with_progress(g, progress)?,
            progress,
            readback.as_mut(),
        )?;
        Ok(readback)
    })?;
    cut(
        hook,
        &format!("{}:{index}", if kind == 0 { "detach" } else { "attach" }),
    )?;

    ensure(
        self.db.execute(
            "UPDATE active SET tip=?,generation=?,state_slot=? WHERE singleton=1",
            params![target.as_slice(), g, g],
        )? == 1,
        "STORAGE_WRITE",
    )
    .map_err(Error::local_integrity)?;
    ensure(
        self.db.execute(
            "INSERT INTO events SELECT ?,ordinal,kind,block FROM steps ORDER BY ordinal",
            [g],
        )? == expected.len(),
        "STORAGE_WRITE",
    )
    .map_err(Error::local_integrity)?;
    ensure(
        self.db
            .execute("UPDATE reorg SET done=1 WHERE singleton=1", [])?
            == 1,
        "STORAGE_WRITE",
    )
    .map_err(Error::local_integrity)?;
    self.finish_reorg_lifecycle(old, target, g)?;
    self.db.execute("DELETE FROM kv WHERE slot!=?", [g])?;
    ensure(
        self.active()? == (target, g) && self.slot()? == g,
        "GENERATION",
    )
    .map_err(Error::local_integrity)?;
    self.check_reorg_row(old, target, g, count, 1)?;
    self.check_events_with_progress(g, &expected, progress)?;
    let mut readback = self.reorg_post_write_readback(target, original_owner)?;
    self.check_persisted_state_with_readback(
        target,
        &self.slot_state_with_progress(g, progress)?,
        progress,
        readback.as_mut(),
    )?;
    Ok(readback)
})?;
cut(hook, "published")?;
Ok(target)

pub(super) fn finish_or_cancel_reorg(
    &self,
    reservation: &Reservation,
    outcome: Result<Hash>,
    hook: &mut Option<&mut Hook<'_>>,
) -> Result<Hash> {
    let Err(error) = outcome else {
        return outcome;
    };
    if error.kind() != crate::ErrorKind::Cancelled
        && !error.is(crate::ErrorCode::PublicMutationCpuBudget)
        && !error.is(crate::ErrorCode::OwnerContinuousCpuBudget)
    {
        return Err(error);
    }
    let reason = error
        .code()
        .map_or("LOCAL_CANCELLED", crate::ErrorCode::as_str);
    self.cancel_unpublished_reorg(reservation, reason, hook)
        .map_err(Error::local_integrity)?;
    // Keep the original nonterminal local outcome. No terminal peer ACK,
    // nonce advancement or completed activation is fabricated by cleanup.
    Err(error)

let cursor: u64 =
    self.db
        .query_row("SELECT cursor FROM reorg WHERE singleton=1", [], |row| {
            row.get(0)
        })?;
self.check_reorg_row(
    reservation.old,
    reservation.target,
    reservation.generation,
    cursor,
    0,
)?;
let before = self.db.total_changes();
ensure(self.db.execute(
    "UPDATE reorg_lifecycle_v1 SET outcome=2,cancelled_cursor=?,reason=? WHERE operation=? AND outcome=0",
    params![cursor, reason, reservation.operation.ok_or("REORG_LIFECYCLE")?],
)? == 1, "REORG_LIFECYCLE").map_err(Error::local_integrity)?;
cut(hook, "cancel-lifecycle-written")?;
ensure(self.db.execute(
    "UPDATE reorg SET done=2 WHERE singleton=1 AND done=0 AND old_tip=? AND new_tip=? AND generation=? AND cursor=?",
    params![reservation.old.as_slice(), reservation.target.as_slice(), reservation.generation, cursor],
)? == 1, "REORG_LIFECYCLE").map_err(Error::local_integrity)?;
ensure(
    self.db.total_changes() == before + 2
        && self.active()? == (reservation.old, reservation.generation - 1)
        && self.slot()? == reservation.old_slot,
    "REORG_LIFECYCLE",
)
.map_err(Error::local_integrity)?;
self.check_reserved_reorg_lifecycle(reservation, 2, Some(cursor), reason)?;
self.check_reorg_row(
    reservation.old,
    reservation.target,
    reservation.generation,
    cursor,
    2,
)?;
let commit_observation = (self.state_backend == StateBackend::AuthenticatedV1).then(|| {
    self.authenticated_arithmetic
        .history
        .observe_sql_commit(native_authenticated::SqlCommitSite::ReorgTermination)
});
let commit_result = tx.commit();
if let Some(observation) = commit_observation {
    observation.finish_sql_result(&commit_result);
}
commit_result?;
cut(hook, "cancel-committed")?;
Ok(())
